<?php require __DIR__.'/bootstrap.php';
try{$u=admin_user();global $config;if(!isset($_FILES['file']))fail('File required');$f=$_FILES['file'];if($f['error']!==UPLOAD_ERR_OK)fail('Upload failed');if($f['size']>$config['max_upload_bytes'])fail('File too large');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','image/gif'=>'gif'];if(!isset($allowed[$mime]))fail('Only image files are allowed');$sub=preg_replace('/[^a-z0-9_-]/i','',$_POST['folder']??'products')?:'products';if(!in_array($sub,['products','banners','categories'],true))$sub='products';$dir=$config['upload_dir'].'/'.$sub;if(!is_dir($dir))mkdir($dir,0755,true);$name=bin2hex(random_bytes(12)).'.'.$allowed[$mime];$path=$dir.'/'.$name;if(!move_uploaded_file($f['tmp_name'],$path))fail('Could not save upload',500);$base=rtrim($config['upload_url'],'/').'/'.$sub.'/'.$name;ok(['url'=>$base,'path'=>$path]);}catch(Throwable $e){fail('Server error',500);}
